using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Xml;using System.Collections.Generic;using System.Security.Cryptography;
namespace BeamScheduleFormatter {
sealed class PowSourceFile {
 internal readonly string Id,Name,Kind,Sha256;internal readonly bool RecoveredText;string cachePath,encodedPath;readonly long size;readonly object gate=new object();
 /* Owner (17 November 2026): opening a POW took ~22 s in "read file" because every embedded source (Excel workbook,
    DXF) was un-gzipped, hashed and written out on every open, and re-gzipped on every save. Archive entries now keep
    their stored gzip-base64 text as-is; the file is decoded (and its SHA-256 / size verified) only when its content
    is actually needed, and saving copies the stored text back without compressing again. */
 static readonly string cacheDirectory=CreateCache();
 static string CreateCache(){string dir=Path.Combine(Path.GetTempPath(),"DTCE-PowSources-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);AppDomain.CurrentDomain.ProcessExit+=(s,e)=>{try{Directory.Delete(dir,true);}catch{}};return dir;}
 internal long Size{get{return size;}}internal Stream OpenRead(){Materialize();return new FileStream(cachePath,FileMode.Open,FileAccess.Read,FileShare.Read);}
 PowSourceFile(string name,string kind,string sha,long length,bool recovered,string encoded){Name=SafeName(name);Kind=(kind??"").Trim();if(Kind.Length==0||Kind.Length>100)throw new Exception("Invalid project source kind.");if(sha==null||sha.Length!=64||sha.Any(c=>!((c>='0'&&c<='9')||(c>='a'&&c<='f'))))throw new Exception("Invalid project source metadata.");if(length<0)throw new Exception("Invalid project source metadata.");RecoveredText=recovered;Sha256=sha;size=length;encodedPath=encoded;Id=Hash(Encoding.UTF8.GetBytes(Kind.ToUpperInvariant()+"\0"+Name.ToUpperInvariant()+"\0"+Sha256));}
 // Copies the archive entry's base64 text (current reader position: the File element content) to the cache unchanged.
 internal static PowSourceFile FromArchive(XmlReader reader,string name,string kind,string sha,long length,bool recovered){string encoded=Path.Combine(cacheDirectory,Guid.NewGuid().ToString("N")+".b64");bool ok=false;try{using(var output=new StreamWriter(encoded,false,new UTF8Encoding(false))){char[] buffer=new char[65536];
   while(reader.NodeType==XmlNodeType.Text||reader.NodeType==XmlNodeType.Whitespace||reader.NodeType==XmlNodeType.SignificantWhitespace||reader.NodeType==XmlNodeType.CDATA){if(reader.CanReadValueChunk){int n;while((n=reader.ReadValueChunk(buffer,0,buffer.Length))>0){CheckBase64(buffer,n);output.Write(buffer,0,n);}}else{string v=reader.Value;CheckBase64(v.ToCharArray(),v.Length);output.Write(v);}reader.Read();}}
   var file=new PowSourceFile(name,kind,sha,length,recovered,encoded);ok=true;return file;}finally{if(!ok)try{File.Delete(encoded);}catch{}}}
 static void CheckBase64(char[] text,int count){for(int i=0;i<count;i++){char c=text[i];if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/'||c=='='||c==' '||c=='\r'||c=='\n'||c=='\t'))throw new Exception("Invalid project source payload.");}}
 void Materialize(){lock(gate){if(cachePath!=null)return;string target=Path.Combine(cacheDirectory,Sha256+".bin");lock(cacheDirectory){if(File.Exists(target)){/* same verified content already extracted; the recorded size must still match */if(new FileInfo(target).Length!=size)throw new Exception("Project source size does not match its manifest: "+Name);cachePath=target;return;}}
   string temp=Path.Combine(cacheDirectory,Guid.NewGuid().ToString("N")+".tmp");try{long n=0;string hex;using(var hash=SHA256.Create()){using(var text=new FileStream(encodedPath,FileMode.Open,FileAccess.Read,FileShare.Read))using(var decoded=new System.Security.Cryptography.CryptoStream(text,new FromBase64Transform(FromBase64TransformMode.IgnoreWhiteSpaces),System.Security.Cryptography.CryptoStreamMode.Read))using(var gzip=new GZipStream(decoded,CompressionMode.Decompress))using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[65536];int read;while((read=gzip.Read(buffer,0,buffer.Length))>0){if(n>size-read)throw new Exception("Project source expands beyond its recorded size: "+Name);output.Write(buffer,0,read);hash.TransformBlock(buffer,0,read,null,0);n+=read;}}hash.TransformFinalBlock(new byte[0],0,0);hex=Hex(hash.Hash);}
    if(n!=size||hex!=Sha256)throw new Exception("Project source integrity check failed: "+Name);lock(cacheDirectory){if(File.Exists(target))File.Delete(temp);else File.Move(temp,target);}cachePath=target;}catch{try{File.Delete(temp);}catch{}throw;}}}
 // Integrity check of a stored entry (decodes it once); used by tests and when the content is first needed.
 internal void Verify(){Materialize();}
 void EnsureEncoded(){lock(gate){if(encodedPath!=null&&File.Exists(encodedPath))return;string encoded=Path.Combine(cacheDirectory,Guid.NewGuid().ToString("N")+".b64");try{using(var output=new FileStream(encoded,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var base64=new System.Security.Cryptography.CryptoStream(output,new ToBase64Transform(),System.Security.Cryptography.CryptoStreamMode.Write))using(var gzip=new GZipStream(base64,CompressionMode.Compress,true))using(var input=OpenRead())input.CopyTo(gzip);encodedPath=encoded;}catch{try{File.Delete(encoded);}catch{}throw;}}}
 internal string Text(){using(var input=OpenRead())using(var reader=new StreamReader(input,Encoding.UTF8,true))return reader.ReadToEnd();}
 internal byte[] Bytes(){using(var input=OpenRead())using(var output=new MemoryStream()){input.CopyTo(output);return output.ToArray();}}
 internal void CopyTo(string path){using(var input=OpenRead())using(var output=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None))input.CopyTo(output);}
 internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return Hex(sha.ComputeHash(bytes));}static string Hex(byte[] bytes){return BitConverter.ToString(bytes).Replace("-","").ToLowerInvariant();}
 internal PowSourceFile(string name,string kind,byte[] bytes,bool recovered=false):this(name,kind,new MemoryStream(bytes,false),recovered,true,null){}
 internal static PowSourceFile Capture(string name,string kind,Stream input,bool recovered=false,long? expectedSize=null){return new PowSourceFile(name,kind,input,recovered,false,expectedSize);}
 PowSourceFile(string name,string kind,Stream input,bool recovered,bool ownsInput,long? expectedSize){Name=SafeName(name);Kind=(kind??"").Trim();if(Kind.Length==0||Kind.Length>100)throw new Exception("Invalid project source kind.");RecoveredText=recovered;string temp=Path.Combine(cacheDirectory,Guid.NewGuid().ToString("N")+".tmp");try{using(var hash=SHA256.Create()){using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(expectedSize.HasValue&&size>expectedSize.Value-n)throw new Exception("Project source expands beyond its recorded size.");output.Write(buffer,0,n);hash.TransformBlock(buffer,0,n,null,0);size=checked(size+n);}hash.TransformFinalBlock(new byte[0],0,0);Sha256=Hex(hash.Hash);}if(expectedSize.HasValue&&size!=expectedSize.Value)throw new Exception("Project source size does not match its manifest.");}cachePath=Path.Combine(cacheDirectory,Sha256+".bin");lock(cacheDirectory){if(File.Exists(cachePath))File.Delete(temp);else File.Move(temp,cachePath);}Id=Hash(Encoding.UTF8.GetBytes(Kind.ToUpperInvariant()+"\0"+Name.ToUpperInvariant()+"\0"+Sha256));}catch{try{File.Delete(temp);}catch{}throw;}finally{if(ownsInput)input.Dispose();}}
 internal static string SafeName(string value){value=(value??"").Replace('\\','/');value=value.Substring(value.LastIndexOf('/')+1);if(value.Length==0||value.Length>255||value=="."||value==".."||value.EndsWith(".")||value.EndsWith(" ")||value.Any(c=>c<32||"<>:\"/\\|?*".IndexOf(c)>=0))throw new Exception("Invalid project source filename.");return value;}
 internal void WriteMetadata(XmlWriter writer){writer.WriteAttributeString("id",Id);writer.WriteAttributeString("name",Name);writer.WriteAttributeString("kind",Kind);writer.WriteAttributeString("sha256",Sha256);writer.WriteAttributeString("size",Size.ToString(System.Globalization.CultureInfo.InvariantCulture));writer.WriteAttributeString("recoveredText",RecoveredText.ToString());}
 internal void WritePayload(XmlWriter writer){EnsureEncoded();using(var input=new StreamReader(encodedPath,Encoding.ASCII)){char[] buffer=new char[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0)writer.WriteRaw(buffer,0,n);}}
}
sealed class PowXmlBase64Stream:Stream {
 readonly XmlWriter writer;readonly XmlReader reader;internal PowXmlBase64Stream(XmlWriter value){writer=value;}internal PowXmlBase64Stream(XmlReader value){reader=value;}
 public override bool CanRead{get{return reader!=null;}}public override bool CanWrite{get{return writer!=null;}}public override bool CanSeek{get{return false;}}public override long Length{get{throw new NotSupportedException();}}public override long Position{get{throw new NotSupportedException();}set{throw new NotSupportedException();}}
 public override int Read(byte[] buffer,int offset,int count){return reader.ReadContentAsBase64(buffer,offset,count);}public override void Write(byte[] buffer,int offset,int count){writer.WriteBase64(buffer,offset,count);}public override void Flush(){}public override long Seek(long offset,SeekOrigin origin){throw new NotSupportedException();}public override void SetLength(long value){throw new NotSupportedException();}
}
sealed class PowSourceFiles {
 readonly List<PowSourceFile> files=new List<PowSourceFile>();internal IList<PowSourceFile> Files{get{return files.AsReadOnly();}}internal Action<PowSourceFile> BeforeAdd;
 internal void Add(PowSourceFile file){if(BeforeAdd!=null)BeforeAdd(file);var same=files.Where(f=>f.Name.Equals(file.Name,StringComparison.OrdinalIgnoreCase)&&f.Kind.Equals(file.Kind,StringComparison.OrdinalIgnoreCase)).ToList();if(file.RecoveredText&&same.Any(f=>!f.RecoveredText))return;var remove=file.RecoveredText?new List<PowSourceFile>():same.Where(f=>f.RecoveredText).ToList();if(files.Any(f=>f.Id==file.Id&&!remove.Contains(f)))return;if(!file.RecoveredText&&file.Kind.Equals(WorkbookKind,StringComparison.OrdinalIgnoreCase))remove.AddRange(same.Where(f=>!f.RecoveredText&&!remove.Contains(f)));foreach(var old in remove)files.Remove(old);files.Add(file);}
 internal void AddRange(IEnumerable<PowSourceFile> source){foreach(var file in source)Add(file);}
 /* Owner (19 November 2026, "yung xml file di naman nabawasan ang file size" after Save As): every link of the BACKUP workbook
    added another full copy of it under Project files (one POW held 10 copies, ~245 MB). One copy per workbook name is kept:
    a new copy replaces the older one, and a file that already holds several keeps only the newest (the latest "modified" date
    saved inside the workbook; the copy of the linked workbook when dates are missing). Returns the number of copies dropped. */
 internal const string WorkbookKind="Excel workbook (imported original)";
 internal int KeepNewestWorkbookCopies(string linkedSha=null){int dropped=0;
  foreach(var group in files.Where(f=>!f.RecoveredText&&f.Kind.Equals(WorkbookKind,StringComparison.OrdinalIgnoreCase)).GroupBy(f=>f.Name.ToUpperInvariant()).Where(g=>g.Count()>1).ToList()){
   var ranked=group.Select(f=>new{File=f,Modified=WorkbookModified(f)}).OrderByDescending(x=>x.Modified??DateTime.MinValue).ThenByDescending(x=>linkedSha!=null&&x.File.Sha256==linkedSha).ToList();
   var keep=ranked[0].File;if(ranked.All(x=>x.Modified==null)&&linkedSha!=null){var linked=group.FirstOrDefault(f=>f.Sha256==linkedSha);if(linked!=null)keep=linked;}
   foreach(var f in group)if(f!=keep){files.Remove(f);dropped++;}}
  return dropped;}
 /* dcterms:modified of docProps/core.xml inside an .xlsx / .xlsm copy */
 internal static DateTime? WorkbookModified(PowSourceFile file){try{using(var stream=file.OpenRead())using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){var entry=zip.GetEntry("docProps/core.xml");if(entry==null)return null;using(var core=entry.Open()){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(core,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))doc.Load(reader);foreach(XmlElement e in doc.GetElementsByTagName("*")){if(e.LocalName!="modified")continue;DateTime d;if(DateTime.TryParse(e.InnerText,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.AdjustToUniversal|System.Globalization.DateTimeStyles.AssumeUniversal,out d))return d;}}}}catch(Exception){}return null;}
 internal static PowSourceFile ReadFile(string path,string kind){using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))return PowSourceFile.Capture(Path.GetFileName(path),kind,input);}
 internal void CaptureFile(string path,string kind){Add(ReadFile(path,kind));}
 internal void CaptureText(string name,string kind,string text){if(files.Any(f=>f.Kind==kind&&f.Name.Equals(PowSourceFile.SafeName(name),StringComparison.OrdinalIgnoreCase)))return;Add(new PowSourceFile(name,kind,new UTF8Encoding(false).GetBytes(text??""),true));}
 internal void Replace(PowSourceFiles source){files.Clear();files.AddRange(source.files);}
 internal void WriteStreaming(XmlWriter writer,bool manifestOnly=false){writer.WriteStartElement(manifestOnly?"SourceFileManifest":"SourceFiles");writer.WriteAttributeString("version","1");foreach(var file in files.OrderBy(f=>f.Id,StringComparer.Ordinal)){writer.WriteStartElement("File");file.WriteMetadata(writer);if(!manifestOnly){writer.WriteAttributeString("encoding","gzip-base64");file.WritePayload(writer);}writer.WriteEndElement();}writer.WriteEndElement();}
 internal void Write(XmlElement root,bool manifestOnly=false){var doc=new XmlDocument{XmlResolver=null};using(var text=new StringWriter(System.Globalization.CultureInfo.InvariantCulture)){using(var writer=XmlWriter.Create(text,new XmlWriterSettings{OmitXmlDeclaration=true}))WriteStreaming(writer,manifestOnly);doc.LoadXml(text.ToString());}root.AppendChild(root.OwnerDocument.ImportNode(doc.DocumentElement,true));}
 internal static PowSourceFiles ReadArchive(XmlReader reader,bool verifyNow=true){var result=new PowSourceFiles();if(reader.GetAttribute("version")!="1")throw new Exception("Unsupported project source archive.");bool empty=reader.IsEmptyElement;reader.ReadStartElement("SourceFiles");if(empty)return result;var ids=new HashSet<string>(StringComparer.Ordinal);while(reader.MoveToContent()==XmlNodeType.Element){if(reader.Name!="File")throw new Exception("Invalid project source archive entry.");long size;bool recovered;string name=reader.GetAttribute("name"),kind=reader.GetAttribute("kind"),hash=reader.GetAttribute("sha256"),id=reader.GetAttribute("id");if(!long.TryParse(reader.GetAttribute("size"),out size)||size<0||reader.GetAttribute("encoding")!="gzip-base64"||!bool.TryParse(reader.GetAttribute("recoveredText"),out recovered)||PowSourceFile.SafeName(name)!=name)throw new Exception("Invalid project source metadata.");bool emptyFile=reader.IsEmptyElement;reader.ReadStartElement("File");var file=PowSourceFile.FromArchive(reader,name,kind,hash,size,recovered);if(!emptyFile)reader.ReadEndElement();if(verifyNow)file.Verify();if(file.Sha256!=hash||file.Id!=id||!ids.Add(file.Id))throw new Exception("Project source integrity check failed: "+name);result.Add(file);}reader.ReadEndElement();if(result.Files.Count!=ids.Count)throw new Exception("Duplicate or conflicting project source records.");return result;}
 internal static void ValidateManifest(XmlElement root,PowSourceFiles result,bool hasArchive){var manifest=root.SelectNodes("SourceFileManifest");if(manifest.Count>1)throw new Exception("Duplicate project source manifest.");if(manifest.Count==1){var expected=((XmlElement)manifest[0]).SelectNodes("File").Cast<XmlElement>().Select(e=>e.GetAttribute("id")).OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(!hasArchive&&expected.Length>0)throw new Exception("Saved project is missing its embedded source files.");var actual=result.Files.Select(f=>f.Id).OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(!expected.SequenceEqual(actual))throw new Exception("Embedded project sources do not match the saved manifest.");}}
 internal static PowSourceFiles Read(XmlElement root){var sections=root.SelectNodes("SourceFiles");if(sections.Count>1)throw new Exception("Duplicate project source archive.");var result=new PowSourceFiles();if(sections.Count==1)using(var reader=new XmlNodeReader(sections[0])){reader.MoveToContent();result=ReadArchive(reader);}ValidateManifest(root,result,sections.Count==1);return result;}
}
}
